import '../../domain/entities/teacher_assignment_entity.dart';
class TeacherAssignmentModel extends TeacherAssignmentEntity {
  const TeacherAssignmentModel({required super.id, required super.teacherId, required super.teacherName, required super.classId, required super.sectionId, required super.subject, required super.academicSession, required super.isClassTeacher, required super.createdAt});
  factory TeacherAssignmentModel.fromMap(Map<String,dynamic> map) => TeacherAssignmentModel(id: map['id'] ?? '', teacherId: map['teacherId'] ?? '', teacherName: map['teacherName'] ?? '', classId: map['classId'] ?? '', sectionId: map['sectionId'] ?? '', subject: map['subject'] ?? '', academicSession: map['academicSession'] ?? '', isClassTeacher: map['isClassTeacher'] ?? false, createdAt: DateTime.tryParse(map['createdAt'] ?? '') ?? DateTime.now());
  factory TeacherAssignmentModel.fromEntity(TeacherAssignmentEntity value) => TeacherAssignmentModel(id: value.id, teacherId: value.teacherId, teacherName: value.teacherName, classId: value.classId, sectionId: value.sectionId, subject: value.subject, academicSession: value.academicSession, isClassTeacher: value.isClassTeacher, createdAt: value.createdAt);
  Map<String,dynamic> toMap() => {'id': id, 'teacherId': teacherId, 'teacherName': teacherName, 'classId': classId, 'sectionId': sectionId, 'subject': subject, 'academicSession': academicSession, 'isClassTeacher': isClassTeacher, 'createdAt': createdAt.toIso8601String()};
}
